import{_ as t,o,c as r,a3 as a}from"./chunks/framework.DhF4LrUq.js";const s="/shipperdog/snapshot/screenshots/portal/feedback-dialog.png",g=JSON.parse('{"title":"Submit feedback","description":"Submit feedback in the Tester Portal - the report form, attachments, and what happens after you submit.","frontmatter":{"description":"Submit feedback in the Tester Portal - the report form, attachments, and what happens after you submit."},"headers":[],"relativePath":"how-to/portal/feedback.md","filePath":"how-to/portal/feedback.md"}'),i={name:"how-to/portal/feedback.md"};function n(p,e,h,l,d,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="submit-feedback" tabindex="-1">Submit feedback <a class="header-anchor" href="#submit-feedback" aria-label="Permalink to &quot;Submit feedback&quot;">​</a></h1><p>Found something? On any version page (or any build card in the version history), tap <strong>Report issue</strong>. The form opens with the app, version, and your identity already attached — you only describe what you saw.</p><p><img src="'+s+'" alt="The report form"></p><h2 id="filling-the-form" tabindex="-1">Filling the form <a class="header-anchor" href="#filling-the-form" aria-label="Permalink to &quot;Filling the form&quot;">​</a></h2><ol><li><p><strong>Type</strong> — what kind of report: <strong>Bug</strong>, <strong>Feedback</strong>, <strong>Crash</strong>, <strong>Feature request</strong>, <strong>UX issue</strong>, or <strong>Security issue</strong>.</p></li><li><p><strong>What happened?</strong> — the one required field. What you did, what you expected, what went wrong.</p></li><li><p><strong>Build</strong> — which build you were on. The portal pins the build you were looking at automatically; leave <strong>Not build-specific</strong> if it applies to all of them.</p></li><li><p><strong>Device and OS</strong> — optional; the OS is usually filled in for you. Correct it if your phone knows better.</p></li><li><p><strong>Attachments</strong> — screenshots, screen recordings, or logs help most. <strong>Add file</strong> accepts <code>png</code>, <code>jpg</code>, <code>mp4</code>, <code>txt</code>, and <code>log</code> files, up to five per report.</p></li></ol><p>Tap <strong>Submit report</strong>. You get a confirmation with the report&#39;s reference — your proof it landed.</p><div class="tip custom-block"><p class="custom-block-title">Security reports are private on purpose</p><p>If you pick <strong>Security issue</strong>, only the team members cleared to handle security can see your report — not the whole team. Submit it the same way; the privacy is automatic.</p></div><h2 id="what-happens-after" tabindex="-1">What happens after <a class="header-anchor" href="#what-happens-after" aria-label="Permalink to &quot;What happens after&quot;">​</a></h2><p>Your report lands in the team&#39;s testing queue with everything you saw plus the context you never had to type — app, version, build, device. The team triages it; severe reports can pause a rollout outright, so early reports matter. If the app you are testing carries ShipperDog&#39;s built-in reporter, a crash can also open this form pre-filled — you just check it and submit.</p><p><strong>All guides:</strong> <a href="/shipperdog/snapshot/how-to/portal/accept-invite">accept an invite</a> · <a href="/shipperdog/snapshot/how-to/portal/browse-apps">browse apps</a> · <a href="/shipperdog/snapshot/how-to/portal/install-android">Android</a> · <a href="/shipperdog/snapshot/how-to/portal/install-ios">iOS</a> · <a href="/shipperdog/snapshot/get-started/five-minute-install">the full walkthrough</a></p>',10)])])}const f=t(i,[["render",n]]);export{g as __pageData,f as default};
